insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '67b3dc7f-ae95-53c6-8a85-d47db4b8b37e', e.id, 'LC', (select id from public.content_components where code = 'LC.TXT.CONT.FIL'), 'qa_passed', 'continuous', '{"title":"La amistad según Aristóteles","text":"En su Ética, Aristóteles distingue tres clases de amistad. Hay amistades por utilidad, en las que cada uno busca lo que el otro le ofrece, como ocurre entre socios de un negocio. Hay amistades por placer, que nacen de lo agradable de la compañía, como suele ocurrir entre jóvenes que comparten fiestas. Y hay amistades por la virtud, en las que cada uno quiere el bien del otro por lo que el otro es.\n\nLas dos primeras no son falsas, pero son frágiles: cuando desaparece la utilidad o el placer, la amistad se acaba. La tercera, en cambio, es duradera, porque el carácter de las personas cambia mucho más despacio que sus intereses. Aristóteles advierte que esta amistad es rara y requiere tiempo: no basta con desearla, hay que haber compartido mucho para conocerse.\n\n(Texto de divulgación escrito para esta prueba a partir de ideas de Aristóteles)","svg":null,"table":null}'::jsonb, 'Según el texto, ¿qué caracteriza a la amistad por utilidad?', '[{"label":"A","text":"Es la más duradera de todas.","is_correct":false,"distractor_type":"Atribuye la duración a otra clase.","explanation_feedback":"Incorrecta. La más duradera es la amistad por virtud."},{"label":"B","text":"Nace de compartir fiestas.","is_correct":false,"distractor_type":"Confunde con la amistad por placer.","explanation_feedback":"Incorrecta. Esa es la segunda clase."},{"label":"C","text":"Cada uno busca lo que el otro le ofrece.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El texto lo explica con el ejemplo de los socios."},{"label":"D","text":"Cada uno quiere el bien del otro.","is_correct":false,"distractor_type":"Confunde con la amistad por virtud.","explanation_feedback":"Incorrecta. Esa es la tercera clase."}]'::jsonb, null, 0.9, -1.2, 0.25, 60, 'original_generated'
from public.evidences e where e.code = 'LC.E1.1'
on conflict (id) do nothing;
