insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '1bb7e8f3-4454-52f3-886a-ef45a8c1b138', e.id, 'LC', (select id from public.content_components where code = 'LC.TXT.CONT.FIL'), 'qa_passed', 'continuous', '{"title":"El velo de la ignorancia","text":"El filósofo estadounidense John Rawls propuso un experimento mental para pensar la justicia. Imaginemos que un grupo de personas debe decidir las reglas de una sociedad sin saber qué lugar ocuparán en ella: no saben si serán ricas o pobres, hombres o mujeres, sanas o enfermas, ni qué talentos tendrán. Rawls llama a esta situación el «velo de la ignorancia».\n\nSegún Rawls, detrás de ese velo nadie aceptaría reglas que perjudicaran gravemente a los que están peor, porque cualquiera podría terminar en esa posición. Por eso, las personas elegirían garantizar libertades básicas iguales para todos y aceptarían desigualdades económicas solo si benefician también a los menos favorecidos.\n\nSus críticos señalan que las personas reales no deciden así: conocen su situación y la defienden. Rawls respondería que el experimento no describe cómo decidimos, sino cómo deberíamos decidir si queremos ser imparciales.\n\n(Texto de divulgación escrito para esta prueba)","svg":null,"table":null}'::jsonb, '¿Qué es el «velo de la ignorancia» en el texto?', '[{"label":"A","text":"La falta de educación en una sociedad.","is_correct":false,"distractor_type":"Lee la expresión de forma literal.","explanation_feedback":"Incorrecta. Es un experimento mental, no un problema educativo."},{"label":"B","text":"Una ley que prohíbe conocer a los gobernantes.","is_correct":false,"distractor_type":"Inventa una norma.","explanation_feedback":"Incorrecta. No se trata de una ley."},{"label":"C","text":"Una situación imaginaria en la que no se sabe qué lugar se ocupará en la sociedad.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El primer párrafo lo define."},{"label":"D","text":"Una prenda que usaban los filósofos.","is_correct":false,"distractor_type":"Toma «velo» como objeto.","explanation_feedback":"Incorrecta. Es una metáfora."}]'::jsonb, null, 0.9, -1.2, 0.25, 60, 'original_generated'
from public.evidences e where e.code = 'LC.E1.1'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '242c4314-abdf-58c6-a131-cabc4455d054', e.id, 'LC', (select id from public.content_components where code = 'LC.TXT.CONT.FIL'), 'qa_passed', 'continuous', '{"title":"El velo de la ignorancia","text":"El filósofo estadounidense John Rawls propuso un experimento mental para pensar la justicia. Imaginemos que un grupo de personas debe decidir las reglas de una sociedad sin saber qué lugar ocuparán en ella: no saben si serán ricas o pobres, hombres o mujeres, sanas o enfermas, ni qué talentos tendrán. Rawls llama a esta situación el «velo de la ignorancia».\n\nSegún Rawls, detrás de ese velo nadie aceptaría reglas que perjudicaran gravemente a los que están peor, porque cualquiera podría terminar en esa posición. Por eso, las personas elegirían garantizar libertades básicas iguales para todos y aceptarían desigualdades económicas solo si benefician también a los menos favorecidos.\n\nSus críticos señalan que las personas reales no deciden así: conocen su situación y la defienden. Rawls respondería que el experimento no describe cómo decidimos, sino cómo deberíamos decidir si queremos ser imparciales.\n\n(Texto de divulgación escrito para esta prueba)","svg":null,"table":null}'::jsonb, 'Según Rawls, ¿por qué las personas detrás del velo protegerían a los menos favorecidos?', '[{"label":"A","text":"Porque la ley las obliga.","is_correct":false,"distractor_type":"Introduce una obligación externa.","explanation_feedback":"Incorrecta. Están decidiendo las leyes, no obedeciéndolas."},{"label":"B","text":"Porque todas son personas generosas.","is_correct":false,"distractor_type":"Atribuye una motivación moral distinta.","explanation_feedback":"Incorrecta. El argumento se basa en la incertidumbre, no en la bondad."},{"label":"C","text":"Porque saben que serán pobres.","is_correct":false,"distractor_type":"Contradice el experimento.","explanation_feedback":"Incorrecta. No saben si serán ricas o pobres."},{"label":"D","text":"Porque cualquiera de ellas podría terminar en esa posición.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Al no saber su lugar, se protegen a sí mismas."}]'::jsonb, null, 1.1, 0, 0.25, 100, 'original_generated'
from public.evidences e where e.code = 'LC.E2.3'
on conflict (id) do nothing;
