insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '5939bd0e-dbd8-5dc2-a988-470b43113061', e.id, 'LC', (select id from public.content_components where code = 'LC.TXT.CONT.FIL'), 'qa_passed', 'continuous', '{"title":"¿Podemos conocer el mundo?","text":"René Descartes se propuso dudar de todo lo que pudiera ponerse en duda para encontrar algo absolutamente cierto. Los sentidos a veces nos engañan: un palo dentro del agua parece doblado. Los sueños pueden ser tan vívidos que, mientras soñamos, creemos estar despiertos. ¿Cómo saber, entonces, que lo que vemos ahora no es un sueño?\n\nEn medio de esa duda radical, Descartes encontró una certeza: aunque dude de todo, no puedo dudar de que estoy dudando, y si dudo, pienso; y si pienso, existo. De ahí su célebre frase «Pienso, luego existo».\n\nOtros filósofos, como David Hume, desconfiaron de ese punto de partida. Para Hume, todo lo que sabemos proviene de la experiencia, y la mente no es más que un conjunto de percepciones que se suceden. Mientras Descartes buscaba la certeza en la razón, Hume la buscaba, con más modestia, en la experiencia.\n\n(Texto de divulgación escrito para esta prueba)","svg":null,"table":null}'::jsonb, '¿Para qué usa Descartes el ejemplo del palo dentro del agua?', '[{"label":"A","text":"Para criticar a Hume.","is_correct":false,"distractor_type":"Atribuye una intención ausente.","explanation_feedback":"Incorrecta. El ejemplo se refiere a los sentidos."},{"label":"B","text":"Para mostrar que los sentidos pueden engañarnos.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El palo parece doblado aunque no lo está."},{"label":"C","text":"Para explicar la refracción de la luz.","is_correct":false,"distractor_type":"Lee el ejemplo como explicación física.","explanation_feedback":"Incorrecta. El ejemplo apoya una idea filosófica."},{"label":"D","text":"Para demostrar que existe.","is_correct":false,"distractor_type":"Confunde el ejemplo con la conclusión.","explanation_feedback":"Incorrecta. La certeza de existir viene de la duda, no del palo."}]'::jsonb, null, 0.9, -1.2, 0.25, 60, 'original_generated'
from public.evidences e where e.code = 'LC.E1.1'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select 'b8908b95-de9a-5362-8ee1-9d00d2243d4d', e.id, 'LC', (select id from public.content_components where code = 'LC.TXT.CONT.FIL'), 'qa_passed', 'continuous', '{"title":"¿Podemos conocer el mundo?","text":"René Descartes se propuso dudar de todo lo que pudiera ponerse en duda para encontrar algo absolutamente cierto. Los sentidos a veces nos engañan: un palo dentro del agua parece doblado. Los sueños pueden ser tan vívidos que, mientras soñamos, creemos estar despiertos. ¿Cómo saber, entonces, que lo que vemos ahora no es un sueño?\n\nEn medio de esa duda radical, Descartes encontró una certeza: aunque dude de todo, no puedo dudar de que estoy dudando, y si dudo, pienso; y si pienso, existo. De ahí su célebre frase «Pienso, luego existo».\n\nOtros filósofos, como David Hume, desconfiaron de ese punto de partida. Para Hume, todo lo que sabemos proviene de la experiencia, y la mente no es más que un conjunto de percepciones que se suceden. Mientras Descartes buscaba la certeza en la razón, Hume la buscaba, con más modestia, en la experiencia.\n\n(Texto de divulgación escrito para esta prueba)","svg":null,"table":null}'::jsonb, '¿Cómo llega Descartes a la certeza de que existe?', '[{"label":"A","text":"Al notar que no puede dudar de que duda.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El segundo párrafo reconstruye el razonamiento."},{"label":"B","text":"Al confiar plenamente en sus sentidos.","is_correct":false,"distractor_type":"Contradice el texto.","explanation_feedback":"Incorrecta. Descartes desconfía de los sentidos."},{"label":"C","text":"Al leer con cuidado las obras de Hume.","is_correct":false,"distractor_type":"Confunde la cronología y la relación.","explanation_feedback":"Incorrecta. El texto no dice que lo leyera."},{"label":"D","text":"Al comprobar que no está soñando.","is_correct":false,"distractor_type":"Supone un paso que no aparece.","explanation_feedback":"Incorrecta. Descartes no prueba que no sueña."}]'::jsonb, null, 1.1, 0, 0.25, 100, 'original_generated'
