insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '7a0c975d-6b40-5b38-bfa1-f15bc8d6e040', e.id, 'LC', (select id from public.content_components where code = 'LC.TXT.CONT.FIL'), 'qa_passed', 'continuous', '{"title":"La caverna","text":"Platón imaginó a unos prisioneros encadenados desde niños en el fondo de una caverna, de cara a una pared. Detrás de ellos arde un fuego, y entre el fuego y los prisioneros pasan personas que cargan objetos. Los prisioneros solo ven las sombras de esos objetos en la pared y creen que esas sombras son la realidad.\n\nSi uno de ellos fuera liberado y saliera al exterior, la luz del sol primero lo cegaría y le dolería. Poco a poco vería los objetos reales y, al final, el sol mismo. Si regresara a contarles a los demás lo que vio, ellos se burlarían de él y quizá intentarían matarlo, porque preferirían sus sombras conocidas.\n\nPlatón usa esta alegoría para hablar de la educación: aprender no es llenar una mente vacía, sino girarla hacia la luz, un proceso que puede ser doloroso y que no siempre es bien recibido por los demás.\n\n(Texto de divulgación escrito para esta prueba)","svg":null,"table":null}'::jsonb, '¿Qué ven los prisioneros en la pared de la caverna?', '[{"label":"A","text":"Las sombras de los objetos.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El primer párrafo lo describe."},{"label":"B","text":"Los objetos reales que pasan.","is_correct":false,"distractor_type":"Confunde objetos con sombras.","explanation_feedback":"Incorrecta. Solo ven sombras."},{"label":"C","text":"A las personas que cargan objetos.","is_correct":false,"distractor_type":"Confunde quiénes son visibles.","explanation_feedback":"Incorrecta. Ven sus sombras, no a ellas."},{"label":"D","text":"El sol del exterior.","is_correct":false,"distractor_type":"Confunde con la experiencia del liberado.","explanation_feedback":"Incorrecta. El sol solo lo ve quien sale."}]'::jsonb, null, 0.9, -1.2, 0.25, 45, 'original_generated'
from public.evidences e where e.code = 'LC.E1.2'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '9285d7eb-e734-5264-ba78-32fc80436a18', e.id, 'LC', (select id from public.content_components where code = 'LC.TXT.CONT.FIL'), 'qa_passed', 'continuous', '{"title":"La caverna","text":"Platón imaginó a unos prisioneros encadenados desde niños en el fondo de una caverna, de cara a una pared. Detrás de ellos arde un fuego, y entre el fuego y los prisioneros pasan personas que cargan objetos. Los prisioneros solo ven las sombras de esos objetos en la pared y creen que esas sombras son la realidad.\n\nSi uno de ellos fuera liberado y saliera al exterior, la luz del sol primero lo cegaría y le dolería. Poco a poco vería los objetos reales y, al final, el sol mismo. Si regresara a contarles a los demás lo que vio, ellos se burlarían de él y quizá intentarían matarlo, porque preferirían sus sombras conocidas.\n\nPlatón usa esta alegoría para hablar de la educación: aprender no es llenar una mente vacía, sino girarla hacia la luz, un proceso que puede ser doloroso y que no siempre es bien recibido por los demás.\n\n(Texto de divulgación escrito para esta prueba)","svg":null,"table":null}'::jsonb, '¿Por qué los prisioneros se burlarían del que regresa?', '[{"label":"A","text":"Porque ya conocían el exterior.","is_correct":false,"distractor_type":"Contradice el texto.","explanation_feedback":"Incorrecta. Nunca habían salido."},{"label":"B","text":"Porque prefieren las sombras que conocen a una realidad que desconocen.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El texto dice que preferirían sus sombras conocidas."},{"label":"C","text":"Porque el liberado miente sobre lo que vio.","is_correct":false,"distractor_type":"Supone una mentira.","explanation_feedback":"Incorrecta. El liberado cuenta lo que realmente vio."},{"label":"D","text":"Porque el liberado se volvió ciego para siempre.","is_correct":false,"distractor_type":"Exagera la ceguera.","explanation_feedback":"Incorrecta. La ceguera es solo al principio."}]'::jsonb, null, 1.1, 0, 0.25, 100, 'original_generated'
from public.evidences e where e.code = 'LC.E2.3'
