select 'f277a482-e00f-5df6-8211-9f90d8527f15', e.id, 'LC', (select id from public.content_components where code = 'LC.TXT.CONT.FIL'), 'qa_passed', 'continuous', '{"title":"La caverna","text":"Platón imaginó a unos prisioneros encadenados desde niños en el fondo de una caverna, de cara a una pared. Detrás de ellos arde un fuego, y entre el fuego y los prisioneros pasan personas que cargan objetos. Los prisioneros solo ven las sombras de esos objetos en la pared y creen que esas sombras son la realidad.\n\nSi uno de ellos fuera liberado y saliera al exterior, la luz del sol primero lo cegaría y le dolería. Poco a poco vería los objetos reales y, al final, el sol mismo. Si regresara a contarles a los demás lo que vio, ellos se burlarían de él y quizá intentarían matarlo, porque preferirían sus sombras conocidas.\n\nPlatón usa esta alegoría para hablar de la educación: aprender no es llenar una mente vacía, sino girarla hacia la luz, un proceso que puede ser doloroso y que no siempre es bien recibido por los demás.\n\n(Texto de divulgación escrito para esta prueba)","svg":null,"table":null}'::jsonb, 'Según el último párrafo, ¿qué representa la salida de la caverna?', '[{"label":"A","text":"La educación, que gira la mente hacia la luz.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Platón usa la alegoría para hablar de la educación."},{"label":"B","text":"Un viaje de turismo fuera de casa.","is_correct":false,"distractor_type":"Banaliza el sentido.","explanation_feedback":"Incorrecta. No es un paseo."},{"label":"C","text":"Un castigo para los curiosos.","is_correct":false,"distractor_type":"Invierte el sentido.","explanation_feedback":"Incorrecta. Salir es un avance, aunque doloroso."},{"label":"D","text":"Un escape de una cárcel real.","is_correct":false,"distractor_type":"Lee la alegoría literalmente.","explanation_feedback":"Incorrecta. Es una alegoría."}]'::jsonb, null, 1.3, 1.3, 0.25, 100, 'original_generated'
from public.evidences e where e.code = 'LC.E3.5'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '2abee080-60b2-5435-a87a-41b3eb2bddb1', e.id, 'LC', (select id from public.content_components where code = 'LC.TXT.CONT.FIL'), 'qa_passed', 'continuous', '{"title":"La caverna","text":"Platón imaginó a unos prisioneros encadenados desde niños en el fondo de una caverna, de cara a una pared. Detrás de ellos arde un fuego, y entre el fuego y los prisioneros pasan personas que cargan objetos. Los prisioneros solo ven las sombras de esos objetos en la pared y creen que esas sombras son la realidad.\n\nSi uno de ellos fuera liberado y saliera al exterior, la luz del sol primero lo cegaría y le dolería. Poco a poco vería los objetos reales y, al final, el sol mismo. Si regresara a contarles a los demás lo que vio, ellos se burlarían de él y quizá intentarían matarlo, porque preferirían sus sombras conocidas.\n\nPlatón usa esta alegoría para hablar de la educación: aprender no es llenar una mente vacía, sino girarla hacia la luz, un proceso que puede ser doloroso y que no siempre es bien recibido por los demás.\n\n(Texto de divulgación escrito para esta prueba)","svg":null,"table":null}'::jsonb, '¿Qué se puede inferir sobre la idea de educación de Platón?', '[{"label":"A","text":"Que es mejor quedarse con lo conocido.","is_correct":false,"distractor_type":"Adopta la posición de los prisioneros.","explanation_feedback":"Incorrecta. Platón valora la salida."},{"label":"B","text":"Que el conocimiento verdadero puede incomodar y encontrar resistencia.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El liberado sufre la luz y es rechazado al volver."},{"label":"C","text":"Que la educación consiste en memorizar datos.","is_correct":false,"distractor_type":"Contradice la idea de «girar la mente».","explanation_feedback":"Incorrecta. Platón niega que sea llenar una mente vacía."},{"label":"D","text":"Que aprender siempre es agradable y rápido.","is_correct":false,"distractor_type":"Contradice el texto.","explanation_feedback":"Incorrecta. El texto habla de dolor y de un proceso gradual."}]'::jsonb, null, 1.3, 1.3, 0.25, 100, 'original_generated'
from public.evidences e where e.code = 'LC.E3.1'
