insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select 'cbf66d0d-27fe-5f96-9af9-ecec7d53e3f8', e.id, 'LC', (select id from public.content_components where code = 'LC.TXT.CONT.FIL'), 'qa_passed', 'continuous', '{"title":"Kant y la mentira","text":"Immanuel Kant sostuvo que una acción es moralmente correcta si podemos querer que la regla que la guía se convierta en ley universal, es decir, que todos actúen según ella. Para probar una regla, basta preguntarse: ¿qué pasaría si todos hicieran lo mismo?\n\nTomemos la mentira. Si alguien miente para salir de un apuro, su regla sería: «mentir cuando me convenga». Pero si todos mintieran cuando les conviene, nadie le creería a nadie y la mentira misma dejaría de funcionar. La regla se destruye al universalizarse. Por eso, para Kant, mentir es incorrecto aunque traiga buenas consecuencias.\n\nMuchos han objetado este rigor con un caso extremo: ¿debería decirle la verdad a un asesino que pregunta dónde se esconde mi amigo? Kant respondió que sí, lo que para sus críticos muestra que una ética basada solo en reglas puede chocar con la intuición moral.\n\n(Texto de divulgación escrito para esta prueba)","svg":null,"table":null}'::jsonb, 'Según el texto, ¿qué pregunta propone Kant para evaluar una regla?', '[{"label":"A","text":"«¿Qué pasaría si todos hicieran lo mismo?».","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Lo dice el primer párrafo."},{"label":"B","text":"«¿Qué gano yo con esta acción?».","is_correct":false,"distractor_type":"Confunde con una ética de beneficio propio.","explanation_feedback":"Incorrecta. Kant pide universalizar, no calcular beneficios."},{"label":"C","text":"«¿Qué dice la ley del país?».","is_correct":false,"distractor_type":"Confunde ley moral con ley civil.","explanation_feedback":"Incorrecta. La ley universal es un criterio moral."},{"label":"D","text":"«¿Qué opina la mayoría?».","is_correct":false,"distractor_type":"Confunde con un criterio de opinión.","explanation_feedback":"Incorrecta. Kant no consulta la opinión mayoritaria."}]'::jsonb, null, 0.9, -1.2, 0.25, 60, 'original_generated'
from public.evidences e where e.code = 'LC.E1.1'
on conflict (id) do nothing;
