select '5b608498-36e7-562e-a716-3edfb65b29c2', e.id, 'LC', (select id from public.content_components where code = 'LC.TXT.CONT.FIL'), 'qa_passed', 'continuous', '{"title":"Epicuro y la felicidad","text":"Al filósofo griego Epicuro se le ha acusado durante siglos de promover el exceso: comer, beber y gozar sin medida. Nada más lejano de su pensamiento. Para Epicuro, el placer es el bien, pero entendido como ausencia de dolor en el cuerpo y de angustia en el alma.\n\nPor eso distinguía entre deseos. Algunos son naturales y necesarios, como comer cuando se tiene hambre o tener un techo. Otros son naturales pero no necesarios, como comer platos refinados. Y otros no son ni naturales ni necesarios, como la fama o la riqueza ilimitada. Quien persigue estos últimos nunca queda satisfecho, porque siempre hay más que desear.\n\nLa vida feliz, según Epicuro, es sencilla: pan, agua, amigos y conversación. Su escuela, el Jardín, era famosa justamente por eso.\n\n(Texto de divulgación escrito para esta prueba)","svg":null,"table":null}'::jsonb, 'Según el texto, ¿qué entendía Epicuro por placer?', '[{"label":"A","text":"Tener mucha fama y riqueza.","is_correct":false,"distractor_type":"Confunde con deseos que Epicuro rechaza.","explanation_feedback":"Incorrecta. La fama no es natural ni necesaria."},{"label":"B","text":"Comer y beber sin medida.","is_correct":false,"distractor_type":"Repite la acusación que el texto rechaza.","explanation_feedback":"Incorrecta. El texto dice que eso es lo contrario de su pensamiento."},{"label":"C","text":"No sentir dolor ni angustia.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El primer párrafo lo define."},{"label":"D","text":"Comer platos refinados.","is_correct":false,"distractor_type":"Confunde con un deseo no necesario.","explanation_feedback":"Incorrecta. Ese deseo es natural, pero no necesario."}]'::jsonb, null, 0.9, -1.2, 0.25, 60, 'original_generated'
from public.evidences e where e.code = 'LC.E1.1'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '0f2f1fc4-7865-574b-a6b9-8b98c02e9740', e.id, 'LC', (select id from public.content_components where code = 'LC.TXT.CONT.FIL'), 'qa_passed', 'continuous', '{"title":"Epicuro y la felicidad","text":"Al filósofo griego Epicuro se le ha acusado durante siglos de promover el exceso: comer, beber y gozar sin medida. Nada más lejano de su pensamiento. Para Epicuro, el placer es el bien, pero entendido como ausencia de dolor en el cuerpo y de angustia en el alma.\n\nPor eso distinguía entre deseos. Algunos son naturales y necesarios, como comer cuando se tiene hambre o tener un techo. Otros son naturales pero no necesarios, como comer platos refinados. Y otros no son ni naturales ni necesarios, como la fama o la riqueza ilimitada. Quien persigue estos últimos nunca queda satisfecho, porque siempre hay más que desear.\n\nLa vida feliz, según Epicuro, es sencilla: pan, agua, amigos y conversación. Su escuela, el Jardín, era famosa justamente por eso.\n\n(Texto de divulgación escrito para esta prueba)","svg":null,"table":null}'::jsonb, '¿Por qué, según Epicuro, la persona que busca riqueza ilimitada no es feliz?', '[{"label":"A","text":"Porque siempre hay más que desear y nunca queda satisfecha.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Lo dice el segundo párrafo."},{"label":"B","text":"Porque ser rico causa enfermedades.","is_correct":false,"distractor_type":"Inventa una causa.","explanation_feedback":"Incorrecta. El texto no lo dice."},{"label":"C","text":"Porque los amigos la rechazan.","is_correct":false,"distractor_type":"Inventa una consecuencia.","explanation_feedback":"Incorrecta. No se menciona el rechazo."},{"label":"D","text":"Porque la riqueza es ilegal.","is_correct":false,"distractor_type":"Inventa una razón.","explanation_feedback":"Incorrecta. No se habla de legalidad."}]'::jsonb, null, 1.1, 0, 0.25, 60, 'original_generated'
