insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '7bdae35c-5eb1-527f-9df9-6ae866eb90d7', e.id, 'LC', (select id from public.content_components where code = 'LC.TXT.CONT.FIL'), 'qa_passed', 'continuous', '{"title":"Epicuro y la felicidad","text":"Al filósofo griego Epicuro se le ha acusado durante siglos de promover el exceso: comer, beber y gozar sin medida. Nada más lejano de su pensamiento. Para Epicuro, el placer es el bien, pero entendido como ausencia de dolor en el cuerpo y de angustia en el alma.\n\nPor eso distinguía entre deseos. Algunos son naturales y necesarios, como comer cuando se tiene hambre o tener un techo. Otros son naturales pero no necesarios, como comer platos refinados. Y otros no son ni naturales ni necesarios, como la fama o la riqueza ilimitada. Quien persigue estos últimos nunca queda satisfecho, porque siempre hay más que desear.\n\nLa vida feliz, según Epicuro, es sencilla: pan, agua, amigos y conversación. Su escuela, el Jardín, era famosa justamente por eso.\n\n(Texto de divulgación escrito para esta prueba)","svg":null,"table":null}'::jsonb, '¿Qué valor destaca el texto en la propuesta de Epicuro?', '[{"label":"A","text":"La competencia entre las personas.","is_correct":false,"distractor_type":"Introduce un valor ajeno.","explanation_feedback":"Incorrecta. Epicuro no exalta la competencia."},{"label":"B","text":"La sencillez como camino hacia la tranquilidad.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. «La vida feliz... es sencilla»."},{"label":"C","text":"La acumulación de bienes.","is_correct":false,"distractor_type":"Contradice el texto.","explanation_feedback":"Incorrecta. La riqueza ilimitada no da felicidad."},{"label":"D","text":"La obediencia a las autoridades.","is_correct":false,"distractor_type":"Introduce un valor ausente.","explanation_feedback":"Incorrecta. El texto no habla de autoridad."}]'::jsonb, null, 1.3, 1.3, 0.25, 100, 'original_generated'
