insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select 'e4311bf8-65b2-55ca-825e-63b8ef69a2c9', e.id, 'LC', (select id from public.content_components where code = 'LC.TXT.CONT.FIL'), 'qa_passed', 'continuous', '{"title":"¿Qué es el tiempo?","text":"San Agustín escribió una frase que todavía se cita: «Si nadie me lo pregunta, sé lo que es el tiempo; si quiero explicárselo a quien me lo pregunta, no lo sé». Usamos la palabra a diario sin dificultad, pero al intentar definirla aparecen las paradojas.\n\nEl pasado ya no es; el futuro todavía no es; y el presente, si durara, ya no sería presente sino pasado. ¿Dónde está, entonces, el tiempo? Agustín propuso que el tiempo existe en la mente: el pasado está en la memoria, el futuro en la espera y el presente en la atención.\n\nSiglos después, la física describiría el tiempo como una dimensión medible, ligada al espacio. Pero la pregunta de Agustín sigue viva, porque no se refiere a cómo medimos el tiempo, sino a cómo lo vivimos.\n\n(Texto de divulgación escrito para esta prueba)","svg":null,"table":null}'::jsonb, '¿Qué expresa la frase de San Agustín citada al inicio?', '[{"label":"A","text":"Que el tiempo en realidad no existe.","is_correct":false,"distractor_type":"Exagera la idea.","explanation_feedback":"Incorrecta. Agustín no niega el tiempo."},{"label":"B","text":"Que solo los físicos saben qué es el tiempo.","is_correct":false,"distractor_type":"Introduce una idea posterior.","explanation_feedback":"Incorrecta. La física aparece después en el texto."},{"label":"C","text":"Que nunca le preguntan por el tiempo.","is_correct":false,"distractor_type":"Lee la frase literalmente.","explanation_feedback":"Incorrecta. Es una reflexión, no un dato."},{"label":"D","text":"Que lo entendemos, pero no sabemos definirlo.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Sabe qué es mientras no tenga que explicarlo."}]'::jsonb, null, 1.1, 0, 0.25, 75, 'original_generated'
from public.evidences e where e.code = 'LC.E1.1'
on conflict (id) do nothing;
