select 'c64c1e16-169d-5052-b9a7-21d16a3e5821', e.id, 'LC', (select id from public.content_components where code = 'LC.TXT.CONT.FIL'), 'qa_passed', 'continuous', '{"title":"¿Qué es el tiempo?","text":"San Agustín escribió una frase que todavía se cita: «Si nadie me lo pregunta, sé lo que es el tiempo; si quiero explicárselo a quien me lo pregunta, no lo sé». Usamos la palabra a diario sin dificultad, pero al intentar definirla aparecen las paradojas.\n\nEl pasado ya no es; el futuro todavía no es; y el presente, si durara, ya no sería presente sino pasado. ¿Dónde está, entonces, el tiempo? Agustín propuso que el tiempo existe en la mente: el pasado está en la memoria, el futuro en la espera y el presente en la atención.\n\nSiglos después, la física describiría el tiempo como una dimensión medible, ligada al espacio. Pero la pregunta de Agustín sigue viva, porque no se refiere a cómo medimos el tiempo, sino a cómo lo vivimos.\n\n(Texto de divulgación escrito para esta prueba)","svg":null,"table":null}'::jsonb, 'Según Agustín, ¿dónde están el pasado, el futuro y el presente?', '[{"label":"A","text":"En los relojes, los calendarios y las agendas.","is_correct":false,"distractor_type":"Confunde con instrumentos de medida.","explanation_feedback":"Incorrecta. Agustín ubica el tiempo en la mente."},{"label":"B","text":"En el espacio, como dice la física.","is_correct":false,"distractor_type":"Confunde las dos visiones.","explanation_feedback":"Incorrecta. La física es una visión posterior."},{"label":"C","text":"En la espera, la memoria y la atención.","is_correct":false,"distractor_type":"Intercambia pasado y futuro.","explanation_feedback":"Incorrecta. El pasado está en la memoria."},{"label":"D","text":"En la memoria, la espera y la atención, respectivamente.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El segundo párrafo establece esa correspondencia."}]'::jsonb, null, 1.3, 1.3, 0.25, 100, 'original_generated'
