select '24f493ae-ccfc-5a61-88d6-d3b712ee17aa', e.id, 'LC', (select id from public.content_components where code = 'LC.TXT.CONT.FIL'), 'qa_passed', 'continuous', '{"title":"¿Qué es el tiempo?","text":"San Agustín escribió una frase que todavía se cita: «Si nadie me lo pregunta, sé lo que es el tiempo; si quiero explicárselo a quien me lo pregunta, no lo sé». Usamos la palabra a diario sin dificultad, pero al intentar definirla aparecen las paradojas.\n\nEl pasado ya no es; el futuro todavía no es; y el presente, si durara, ya no sería presente sino pasado. ¿Dónde está, entonces, el tiempo? Agustín propuso que el tiempo existe en la mente: el pasado está en la memoria, el futuro en la espera y el presente en la atención.\n\nSiglos después, la física describiría el tiempo como una dimensión medible, ligada al espacio. Pero la pregunta de Agustín sigue viva, porque no se refiere a cómo medimos el tiempo, sino a cómo lo vivimos.\n\n(Texto de divulgación escrito para esta prueba)","svg":null,"table":null}'::jsonb, '¿Qué recurso usa el autor en «¿Dónde está, entonces, el tiempo?»?', '[{"label":"A","text":"Una conclusión definitiva sobre el tiempo.","is_correct":false,"distractor_type":"Confunde pregunta con conclusión.","explanation_feedback":"Incorrecta. La pregunta abre la reflexión."},{"label":"B","text":"Una cita de un científico moderno.","is_correct":false,"distractor_type":"Confunde el origen.","explanation_feedback":"Incorrecta. Es una pregunta del autor."},{"label":"C","text":"Una pregunta para que el lector busque un mapa.","is_correct":false,"distractor_type":"Lee la pregunta literalmente.","explanation_feedback":"Incorrecta. Es una pregunta filosófica."},{"label":"D","text":"Una pregunta que resume la paradoja.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Sintetiza el problema antes de la respuesta."}]'::jsonb, null, 1.3, 1.3, 0.25, 100, 'original_generated'
