select '3ba4595d-c49f-50b5-ab54-42a09d5f2f81', e.id, 'LC', (select id from public.content_components where code = 'LC.TXT.CONT.FIL'), 'qa_passed', 'continuous', '{"title":"Un diálogo sobre la tolerancia","text":"—¿Debemos tolerar a los intolerantes? —preguntó Ana.\n—Claro, la tolerancia es para todos —respondió Pedro.\n—Entonces, si un grupo intolerante llega al poder gracias a nuestra tolerancia y prohíbe a los demás, ¿no habremos destruido la tolerancia por practicarla?\n—Visto así… quizá haya que poner un límite.\n—¿Y quién lo pone? Si lo pongo yo, puedo terminar llamando intolerante a cualquiera que piense distinto.\n—Entonces el límite no debería ser pensar distinto, sino intentar impedir que otros piensen distinto.\n\n(Diálogo original inspirado en la llamada «paradoja de la tolerancia», planteada por el filósofo Karl Popper)","svg":null,"table":null}'::jsonb, '¿Qué pregunta inicia el diálogo?', '[{"label":"A","text":"Qué es la paradoja de Popper.","is_correct":false,"distractor_type":"Confunde con la nota final.","explanation_feedback":"Incorrecta. La nota es aclaratoria."},{"label":"B","text":"Por qué Pedro es intolerante.","is_correct":false,"distractor_type":"Inventa una acusación.","explanation_feedback":"Incorrecta. Nadie acusa a Pedro."},{"label":"C","text":"Quién debe gobernar un país.","is_correct":false,"distractor_type":"Confunde con un tema derivado.","explanation_feedback":"Incorrecta. El poder aparece después."},{"label":"D","text":"Si se debe tolerar a los intolerantes.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Es la primera intervención de Ana."}]'::jsonb, null, 0.9, -1.2, 0.25, 45, 'original_generated'
from public.evidences e where e.code = 'LC.E1.1'
