insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '5407d2fb-0db4-556b-991a-ab5aefee9c0f', e.id, 'LC', (select id from public.content_components where code = 'LC.TXT.CONT.FIL'), 'qa_passed', 'continuous', '{"title":"Un diálogo sobre la tolerancia","text":"—¿Debemos tolerar a los intolerantes? —preguntó Ana.\n—Claro, la tolerancia es para todos —respondió Pedro.\n—Entonces, si un grupo intolerante llega al poder gracias a nuestra tolerancia y prohíbe a los demás, ¿no habremos destruido la tolerancia por practicarla?\n—Visto así… quizá haya que poner un límite.\n—¿Y quién lo pone? Si lo pongo yo, puedo terminar llamando intolerante a cualquiera que piense distinto.\n—Entonces el límite no debería ser pensar distinto, sino intentar impedir que otros piensen distinto.\n\n(Diálogo original inspirado en la llamada «paradoja de la tolerancia», planteada por el filósofo Karl Popper)","svg":null,"table":null}'::jsonb, '¿Cómo cambia la posición de Pedro a lo largo del diálogo?', '[{"label":"A","text":"Termina dándole la razón a los intolerantes.","is_correct":false,"distractor_type":"Invierte la conclusión.","explanation_feedback":"Incorrecta. Propone limitar a quien impide pensar."},{"label":"B","text":"Se mantiene igual de principio a fin.","is_correct":false,"distractor_type":"No ve el cambio.","explanation_feedback":"Incorrecta. Pedro admite que quizá haya que poner un límite."},{"label":"C","text":"Pasa de tolerar a todos a aceptar un límite definido con cuidado.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Primero dice «claro» y luego propone un criterio para el límite."},{"label":"D","text":"Pasa a rechazar toda tolerancia.","is_correct":false,"distractor_type":"Exagera el cambio.","explanation_feedback":"Incorrecta. Propone un límite, no eliminar la tolerancia."}]'::jsonb, null, 1.1, 0, 0.25, 100, 'original_generated'
