select 'd4771c25-c568-55f5-a764-1e28e3f475ff', e.id, 'LC', (select id from public.content_components where code = 'LC.TXT.CONT.FIL'), 'qa_passed', 'continuous', '{"title":"Un diálogo sobre la tolerancia","text":"—¿Debemos tolerar a los intolerantes? —preguntó Ana.\n—Claro, la tolerancia es para todos —respondió Pedro.\n—Entonces, si un grupo intolerante llega al poder gracias a nuestra tolerancia y prohíbe a los demás, ¿no habremos destruido la tolerancia por practicarla?\n—Visto así… quizá haya que poner un límite.\n—¿Y quién lo pone? Si lo pongo yo, puedo terminar llamando intolerante a cualquiera que piense distinto.\n—Entonces el límite no debería ser pensar distinto, sino intentar impedir que otros piensen distinto.\n\n(Diálogo original inspirado en la llamada «paradoja de la tolerancia», planteada por el filósofo Karl Popper)","svg":null,"table":null}'::jsonb, '¿Qué problema plantea Ana en su segunda intervención?', '[{"label":"A","text":"Que los intolerantes nunca llegan al poder.","is_correct":false,"distractor_type":"Contradice el planteamiento.","explanation_feedback":"Incorrecta. Ana considera que podrían llegar."},{"label":"B","text":"Que tolerar todo puede destruir la tolerancia.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Si los intolerantes llegan al poder, prohibirán a los demás."},{"label":"C","text":"Que Pedro debe gobernar el país.","is_correct":false,"distractor_type":"Inventa una propuesta.","explanation_feedback":"Incorrecta. No se habla de que Pedro gobierne."},{"label":"D","text":"Que la tolerancia es una mala idea.","is_correct":false,"distractor_type":"Exagera el planteamiento.","explanation_feedback":"Incorrecta. Ana señala una paradoja, no rechaza la tolerancia."}]'::jsonb, null, 1.3, 1.3, 0.25, 100, 'original_generated'
