select 'ebbb0231-d04f-533c-aee8-e810b5e6071b', e.id, 'LC', (select id from public.content_components where code = 'LC.TXT.CONT.FIL'), 'qa_passed', 'continuous', '{"title":"Un diálogo sobre la tolerancia","text":"—¿Debemos tolerar a los intolerantes? —preguntó Ana.\n—Claro, la tolerancia es para todos —respondió Pedro.\n—Entonces, si un grupo intolerante llega al poder gracias a nuestra tolerancia y prohíbe a los demás, ¿no habremos destruido la tolerancia por practicarla?\n—Visto así… quizá haya que poner un límite.\n—¿Y quién lo pone? Si lo pongo yo, puedo terminar llamando intolerante a cualquiera que piense distinto.\n—Entonces el límite no debería ser pensar distinto, sino intentar impedir que otros piensen distinto.\n\n(Diálogo original inspirado en la llamada «paradoja de la tolerancia», planteada por el filósofo Karl Popper)","svg":null,"table":null}'::jsonb, '¿Qué criterio para el límite propone Pedro al final?', '[{"label":"A","text":"No poner ningún límite a nadie.","is_correct":false,"distractor_type":"Contradice el final.","explanation_feedback":"Incorrecta. Pedro sí propone un límite."},{"label":"B","text":"Limitar a quien piense distinto.","is_correct":false,"distractor_type":"Confunde con lo que Ana advierte.","explanation_feedback":"Incorrecta. Pedro rechaza ese criterio."},{"label":"C","text":"Limitar a quien impida pensar distinto.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Es su última intervención."},{"label":"D","text":"Dejar que cada persona ponga su límite.","is_correct":false,"distractor_type":"Inventa un criterio.","explanation_feedback":"Incorrecta. Ana advierte el riesgo de esa opción."}]'::jsonb, null, 1.3, 1.3, 0.25, 75, 'original_generated'
