select '42c6bd69-e036-5f1b-9df4-df719d4f0687', e.id, 'LC', (select id from public.content_components where code = 'LC.TXT.CONT.FIL'), 'qa_passed', 'continuous', '{"title":"Un diálogo sobre la tolerancia","text":"—¿Debemos tolerar a los intolerantes? —preguntó Ana.\n—Claro, la tolerancia es para todos —respondió Pedro.\n—Entonces, si un grupo intolerante llega al poder gracias a nuestra tolerancia y prohíbe a los demás, ¿no habremos destruido la tolerancia por practicarla?\n—Visto así… quizá haya que poner un límite.\n—¿Y quién lo pone? Si lo pongo yo, puedo terminar llamando intolerante a cualquiera que piense distinto.\n—Entonces el límite no debería ser pensar distinto, sino intentar impedir que otros piensen distinto.\n\n(Diálogo original inspirado en la llamada «paradoja de la tolerancia», planteada por el filósofo Karl Popper)","svg":null,"table":null}'::jsonb, '¿Qué función cumple la forma de diálogo en este texto?', '[{"label":"A","text":"Mostrar que Ana y Pedro se odian.","is_correct":false,"distractor_type":"Atribuye una emoción ausente.","explanation_feedback":"Incorrecta. El tono es reflexivo."},{"label":"B","text":"Mostrar cómo un razonamiento avanza mediante preguntas y objeciones.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Las preguntas de Ana hacen que Pedro precise su idea."},{"label":"C","text":"Contar una historia de amor entre Ana y Pedro.","is_correct":false,"distractor_type":"Confunde el tipo de texto.","explanation_feedback":"Incorrecta. Es un diálogo filosófico."},{"label":"D","text":"Reproducir una entrevista real a Popper.","is_correct":false,"distractor_type":"Confunde con la nota final.","explanation_feedback":"Incorrecta. El diálogo es original."}]'::jsonb, null, 1.1, 0, 0.25, 60, 'original_generated'
